  if (!data || !/^[a-f0-9]{32}$/.test(data.device || '')) return null;
  const kind = Object.hasOwn(remoteNames, data.kind) ? data.kind : 'computer';
  return {id: data.device, kind, name: remoteText(data.name, 40) || remoteNames[kind]};
